mapper.select:
select ca.user_allocation_id from wfl_appoint_approver ca where 1=1
and ca.process_instance_id = #{processInstanceId}
and ca.sid_code = #{sidCode}

select
ca.user_allocation_id
from
wfl_appoint_approver ca

    1=1

        and   ca.process_instance_id = #{processInstanceId}


        and   ca.sid_code = #{sidCode}


        and   ca.SOURCE_ID = #{sourceId}


        and   ca.source_table = #{sourceTable}

select ca.APPROVER_ID, ca.SOURCE_ID, ca.USER_ALLOCATION_ID, t.name as USER_ALLOCATION_ID_N, ca.SOURCE_TABLE, ca.SID_CODE, ca.USER_ID, ca.PROCESS_INSTANCE_ID from wfl_appoint_approver ca LEFT JOIN (SELECT sua.allocation_id, fee.name, fc.company_short_name, fn.unit_name, fop.position_name FROM fnd_employee_assigns fea, fnd_employee fee, fnd_org_unit fn, fnd_org_position fop, fnd_company fc, sys_user_allocation sua WHERE fea.employee_id = fee.employee_id AND fn.unit_id = fea.unit_id AND fop.position_id = fea.position_id AND fc.company_id = fea.company_id AND sua.employee_assign_id = fea.employee_assign_id AND sua.allocation_id IS NOT NULL ) t ON ca.USER_ALLOCATION_ID = t.allocation_id where 1=1
and ca.PROCESS_INSTANCE_ID = #{processInstanceId}
and ca.sid_code = #{sidCode}
and ca.SOURCE_ID = #{sourceId}
and ca.source_table = #{sourceTable}
